SELECT dimension_value AS dimensionValue, SUM(pv) AS pv, SUM(uv) AS uv, SUM(conversion_count) AS conversionCount FROM ads_user_behavior WHERE dimension_type IN ('product_view', 'product_cart', 'product_fav')
AND stat_date >= #{startDate}
AND stat_date <= #{endDate}
GROUP BY dimension_value ORDER BY pv DESC LIMIT #{limit}
